ALGORITHME Moyenne_étudiant ;

CONST CoefExam = 2 ; CoefEval = 1 ;

VAR NotExam, NotEval, Moy : Réel ;

DÉBUT

  ÉCRIRE('Donnez la note d'examen : ');

  LIRE(NotExam) ;

  ÉCRIRE('Donnez la note d'évaluation : ');

  LIRE(NotEval) ;

  Moy <- (NotExam * CoefExam + NotEval * CoefEval) / (CoefExam + CoefEval) ;

  ÉCRIRE('La moyenne = ', Moy) ;

FIN.

subsection.content:
POUR compteur ALLANT DE valeur_initiale A valeur_finale FAIRE

  Traitement ;

FIN POUR ;

En langage C :

for (initialisation_du_compteur; expression_de_test; mise_à_jour_du_compteur)

{

  Traitement ;

}

ALGORITHME Affiche ;

VAR i : Entier ;

DÉBUT

  POUR i ALLANT DE 50 A 100 FAIRE

    ÉCRIRE(i) ;

  FIN POUR ;

FIN.

ALGORITHME Moyenne_n_étudiants ;

CONST CoefExam = 2 ; CoefEval = 1 ;

VAR NotExam, NotEval, Moy : Réel ; n, i : Entier ;

DÉBUT

  ÉCRIRE('Combien d'étudiants ? :') ;

  LIRE(n) ;

  POUR i ALLANT DE 1 A n FAIRE

    ÉCRIRE('L'étudiant N° ', i) ;

    ÉCRIRE('Donnez la note d'examen : ') ;

    LIRE(NotExam) ;

    ÉCRIRE('Donnez la note d'évaluation : ') ;

    LIRE(NotEval) ;

    Moy <- (NotExam * CoefExam + NotEval * CoefEval) / (CoefExam + CoefEval) ;

    ÉCRIRE('La moyenne = ', Moy) ;

  FIN POUR ;

FIN.

TANT QUE (condition) FAIRE

  Traitement ;

FIN TANT QUE ;

ALGORITHME Affiche ;

VAR n : Entier ;

DÉBUT

  n <- 50 ; (* Initialisation de la condition *)

  TANT QUE (n <= 100) FAIRE (* Vérification de la condition *)

    ÉCRIRE(n) ;

    n <- n+1 ; (* Mise à jour de la condition *)

  FIN TANT QUE ;

FIN.

ALGORITHME Somme ;

VAR n, i, j, S1, S2 : Entier ;

DÉBUT

  ÉCRIRE('Donnez la valeur de n');

  LIRE(n) ;

  S1 <- 0 ; i <- 1 ;

  TANT QUE (i <= n) FAIRE

    S1 <- S1 + i ;

    i <- i + 1 ;

  FIN TANT QUE ;

  S2 <- 0 ; j <- 1 ;

  TANT QUE (j <= n) FAIRE

    S2 <- S2 + j*j ;

    j <- j + 2 ;

  FIN TANT QUE ;

FIN.

En langage C :

do

{

  Traitement ;

}

while (condition);

ALGORITHME Pair_NbDIV2 ;

VAR N, N2, N3 : Entier ;

DÉBUT

  RÉPÉTER

    ÉCRIRE('Donnez un entier pair') ;

    LIRE(N) ;

  JUSQU'À (N MOD 2 = 0) ;

  N2 <- 0 ;

  N3 <- N ;

  RÉPÉTER

    N3 <- N3 DIV 2 ;

    N2 <- N2 + 1 ;

  JUSQU'À ((N3 MOD 2) <> 0) ;

  ÉCRIRE(N, ' est divisible par 2 ', N2, ' fois ') ;

FIN.
